using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);

// Find source file contents embedded in the binlog
void FindSourceContent(BaseNode node, string path = "")
{
    if (node is SourceFile sf)
    {
        Console.WriteLine($"SourceFile: {sf.Name}");
    }

    if (node is CscCommandLineArgs csc)
    {
        Console.WriteLine($"CSC args: {csc}");
    }

    if (node is Task t && t.Name == "Csc")
    {
        Console.WriteLine($"\nCSC Task in project context:");
        foreach (var child in t.Children.OfType<BaseNode>())
        {
            if (child is Message m)
                Console.WriteLine($"  Message: {m.Text}");
            if (child is Folder f)
                Console.WriteLine($"  Folder: {f.Name}");
            if (child is Parameter p)
                Console.WriteLine($"  Param: {p.Name} = {string.Join(", ", p.Children.OfType<Item>().Select(i => i.Text))}");
        }
    }

    // Look for the commandline message that shows csc invocation
    if (node is Message msg && msg.Text != null && msg.Text.Contains("csc.dll"))
    {
        Console.WriteLine($"\nCSC command: {msg.Text.Substring(0, Math.Min(500, msg.Text.Length))}...");
    }

    if (node is TreeNode tn)
        foreach (var child in tn.Children.OfType<BaseNode>())
            FindSourceContent(child, path);
}

// Get project dependency info
void FindProjectRefs(BaseNode node, string currentProject = "")
{
    if (node is Project p)
    {
        currentProject = p.Name ?? currentProject;
    }

    if (node is TreeNode tn)
    {
        foreach (var child in tn.Children.OfType<BaseNode>())
            FindProjectRefs(child, currentProject);
    }
}

// Check which projects failed
void FindProjectResults(BaseNode node)
{
    if (node is Project p)
    {
        Console.WriteLine($"Project: {p.Name}, Succeeded: {p.Succeeded}");
    }
    if (node is TreeNode tn)
        foreach (var child in tn.Children.OfType<BaseNode>())
            FindProjectResults(child);
}

Console.WriteLine("=== PROJECT BUILD RESULTS ===");
FindProjectResults(build);

Console.WriteLine("\n=== CSC TASK DETAILS ===");
FindSourceContent(build);
